include { BCFTOOLS_VIEW        } from 'nf-core/bcftools/view'
include { ENSEMBLVEP_FILTERVEP } from 'nf-core/ensemblvep/filtervep'
include { HTSLIB_BGZIPTABIX    } from 'nf-core/htslib/bgziptabix'

// Please note this subworkflow requires the options for bcftools_view that are included in the nextflow.config
workflow VCF_FILTER_BCFTOOLS_ENSEMBLVEP {
    take:
    ch_vcf // channel: [ val(meta), path(vcf) ]
    ch_filter_vep_feature_file // channel: [ val(meta), path(txt) ]
    filter_with_bcftools //    bool: should bcftools view be run
    filter_with_filter_vep //    bool: should filter_vep be run

    main:
    ch_tbi = channel.empty()

    // Since bcftools is likely much faster than filter_vep,
    // we run it first to reduce the number of variants that filter_vep has to process.
    if (filter_with_bcftools) {

        BCFTOOLS_VIEW(
            ch_vcf.map { meta, vcf -> [meta, vcf, []] },
            [],
            [],
            [],
        )

        ch_vcf = BCFTOOLS_VIEW.out.vcf
        ch_tbi = BCFTOOLS_VIEW.out.index
    }

    if (filter_with_filter_vep) {

        ENSEMBLVEP_FILTERVEP(
            ch_vcf,
            ch_filter_vep_feature_file.map { _meta, file -> file },
            "vcf"
        )

        HTSLIB_BGZIPTABIX(
            ENSEMBLVEP_FILTERVEP.out.output.map { meta, vcf -> [meta, vcf, [], []] },
            "compress",
            true,
            "vcf"
        )

        ch_vcf = HTSLIB_BGZIPTABIX.out.output
        ch_tbi = HTSLIB_BGZIPTABIX.out.index
    }

    emit:
    vcf      = ch_vcf // channel: [ val(meta), path(vcf) ]
    tbi      = ch_tbi // channel: [ val(meta), path(tbi) ]
}

// IMPORTANT: This config file should be included to ensure that the subworkflow works properly.
process {
    withName: '.*VCF_FILTER_BCFTOOLS_FILTERVEP:BCFTOOLS_VIEW' {
        ext.args   = { [
            '--output-type z',
            '--write-index=tbi',
        ].join(" ") }
    }
}

nextflow_workflow {

    name "Test Subworkflow VCF_FILTER_BCFTOOLS_ENSEMBLVEP"
    script "../main.nf"
    workflow "VCF_FILTER_BCFTOOLS_ENSEMBLVEP"
    config "./nextflow.config"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/vcf_filter_bcftools_ensemblvep"
    tag "bcftools"
    tag "bcftools/view"
    tag "ensemblvep"
    tag "ensemblvep/filtervep"
    tag "htslib"
    tag "htslib/bgziptabix"

    test("vcf, hgnc_ids - filter on expression") {

        when {
            workflow {
                """
                input[0] = Channel.of([
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/vcf/genmod.vcf.gz')
                ])
                input[1] = Channel.of('3084')
                    .collectFile(name: 'hgnc_ids.txt')
                    .map { file -> [ [ id: 'hgnc_ids' ], file ] }
                input[2] = true
                input[3] = false
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(
                    workflow.out.versions.collect { it instanceof String ? path(it).yaml : it },
                    file(workflow.out.tbi[0][1]).name,
                    path(workflow.out.vcf[0][1]).vcf.variantsMD5,
                    path(workflow.out.vcf[0][1]).vcf.summary,
                ).match() }
            )
        }
    }

    test("vcf, hgnc_ids - filter on hgnc ids") {

        when {
            workflow {
                """
                input[0] = Channel.of([
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/vcf/genmod.vcf.gz')
                ])
                input[1] = Channel.of('3084')
                    .collectFile(name: 'hgnc_ids.txt')
                    .map { file -> [ [ id: 'hgnc_ids' ], file ] }
                input[2] = false
                input[3] = true
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(
                    workflow.out.versions.collect { it instanceof String ? path(it).yaml : it },
                    file(workflow.out.tbi[0][1]).name,
                    path(workflow.out.vcf[0][1]).vcf.variantsMD5,
                    path(workflow.out.vcf[0][1]).vcf.summary,
                ).match() }
            )
        }
    }

    test("vcf, hgnc_ids - filter on hgnc ids and expression") {

        when {
            workflow {
                """
                input[0] = Channel.of([
                    [ id:'test' ],
